'use strict';
const data=window.HERB_DATA;
const herbs=data.herbs;
const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const source=id=>data.sources.find(s=>s.id===id);
const herb=id=>herbs.find(h=>h.id===id);
const safeUrl=url=>/^https:\/\//.test(url||'')?escape(url):'#';
const sourceLink=(id,label)=>{const s=source(id);return s?`<a class="small-link" href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${escape(label||s.title)} ↗</a>`:'<span class="table-note">來源尚未收錄</span>'};
let selected=[];let view='workbench';let query='';let filter='全部';let reviewFilter='';let libraryPage=0;let formulaName='四君子湯 · 結構研究';let analyzed=null;let loadedFormulaId='sijunzi';let loadedCorpusFormula=null;let toastTimer;let weightBasis='grams';let analyzedProcessing=null;let massContext={stage:'unrecorded',batch:'',source:''};let preparation='unrecorded';let processPlan=WorkstationModel.defaultPlan();
const roleOptions=['未標註','君','臣','佐','使'];
const colors={'溫熱':'#ab7756','平性':'#839a7d','寒涼':'#63848e','未錄':'#b0b4ab','需辨加工':'#c5ab70'};
function notify(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function seedRow(id,ref){return {id,ratio:1,role:'未標註',grams:null,processingId:'source_unspecified',preparationInstruction:'unrecorded',sourceProcessingNote:ref?.preparation||'',sourceAnnotationText:ref?.annotationText||'',processRecord:{batch:'',stepsNote:'',temperatureC:null,durationMinutes:null,medium:'',equipment:''}}}
function signature(rows){return JSON.stringify(rows.map(x=>({id:x.id,ratio:x.ratio,grams:x.grams??null,processingId:x.processingId||'source_unspecified',processRecord:x.processRecord||{}})).sort((a,b)=>a.id.localeCompare(b.id)))}
function isStale(){return analyzed && (weightBasis!==analyzed.weightBasis||signature(selected)!==signature(analyzed.selection))}
function currentProcessing(options={}){const result=ProcessingModel.resolveSelection(selected,data,window.PROCESSING_DATA,{...options,basis:options.basis||weightBasis});if(!result.valid)throw new Error(result.errors.join('；'));return result}
function analyzeCurrent(){analyzedProcessing=currentProcessing();analyzed=analyzedProcessing.analysis;return analyzedProcessing}
function processingRecord(result=currentProcessing()){return {version:result.version,basis:result.basis,massContext:{...massContext},gramsComplete:result.gramsComplete,totalGrams:result.totalGrams,knownGrams:result.knownGrams,missingGrams:result.missingGrams,resolvedRows:result.resolvedRows,changes:result.changes,analysis:result.analysis,quant:result.quant,limitations:result.limitations}}
function updateMaterial(id,patch,rerender=true){if(rerender&&view==='workbench'&&!validateVisibleRatios()){for(const el of document.querySelectorAll('[data-processing]'))if(el.dataset.processing===id)el.value=selected.find(r=>r.id===id)?.processingId||'source_unspecified';return false}const next=selected.map(s=>s.id===id?{...s,...patch}:s);const result=ProcessingModel.resolveSelection(next,data,window.PROCESSING_DATA,{basis:weightBasis});if(!result.valid){notify(result.errors.join('；'));return false}selected=next;if(rerender)changed();else renderResults();return true}
function loadFormula(id, announce=true){const f=data.formulas.find(f=>f.id===id);if(!f)return;massContext={stage:'unrecorded',batch:'',source:''};preparation='unrecorded';processPlan=WorkstationModel.defaultPlan();selected=f.herbIds.map(id=>seedRow(id,f.ingredientRefs?.find(r=>r.id===id)));loadedFormulaId=id;loadedCorpusFormula=null;formulaName=f.name+' · 結構研究';analyzeCurrent();if(announce)notify('已載入 '+f.name+'；研究份數均設為 1');}
function addHerb(id){if(!herb(id))throw new Error('本草未收錄');if(selected.some(x=>x.id===id)){notify('此味本草已在組方中');return false}selected.push(seedRow(id));loadedFormulaId='';loadedCorpusFormula=null;render();notify('已加入 '+herb(id).name);return true}
function changed(){if(!selected.length){analyzed=null;analyzedProcessing=null;}renderSelection();renderResults();renderCatalog();}
function filteredHerbs(){const q=query.trim().toLocaleLowerCase();return herbs.filter(h=>(!reviewFilter||(reviewFilter==='reviewed'?h.reviewStatus==='curated_source_excerpt_reviewed':h.reviewStatus!=='curated_source_excerpt_reviewed'))&&(filter==='全部'||HerbModel.natureGroup(h.nature)===filter)&&(!q||[h.name,...h.aliases||[],h.nature,...h.flavors||[],...h.meridians||[],source(h.sourceId)?.title||''].join(' ').toLocaleLowerCase().includes(q)))}
function catalogCards(){const found=filteredHerbs();return found.length?found.map(h=>`<article class="herb-card">${HerbImages.thumb(h.id)}<div class="herb-info"><button class="herb-title" data-detail="${escape(h.id)}">${escape(h.name)}${h.toxic?'<span class="risk-mini">慎</span>':''}</button><div class="herb-meta">${escape(h.nature||'性未錄')} · ${escape((h.flavors||[]).join('、')||'味未錄')}</div><span class="herb-image-label">${HerbImages.label(h.id)}</span></div><button class="add-herb ${selected.some(s=>s.id===h.id)?'selected':''}" data-add="${escape(h.id)}" aria-label="${selected.some(s=>s.id===h.id)?'已加入':'加入'}${escape(h.name)}">${selected.some(s=>s.id===h.id)?'✓':'+'}</button></article>`).join(''):'<p class="empty-state">沒有符合的本草。<br>試試其他藥名或性味。</p>'}
function filtersHTML(){return ['全部','溫熱','平性','寒涼'].map(f=>`<button class="filter ${filter===f?'active':''}" data-filter="${f}" aria-pressed="${filter===f}">${f}</button>`).join('')}
function renderCatalog(){const list=$('#herb-list');if(list)list.innerHTML=catalogCards();const filters=$('#catalog-filters');if(filters)filters.innerHTML=filtersHTML();if(view==='library')renderLibraryCards()}
function render(){const titles={workbench:['配伍操作台','核對飲片、實錄稱量與工序，在操作台上查看材料的流向。','配伍工作台'],library:['入藥有據，識草有源。','340 個古籍條目：24 條節錄已核、316 條自動擷取待逐條校勘。','本草資料庫'],classics:['循原文，辨出處。','查看採用的典籍版本、配伍規則與模擬方法。','典籍與規則']};Object.assign(titles,{forward:['以單味建模，回到全方。','量化每味的來源特性，學習成分向量，再與真實原方的文獻方義核對。','藥材模型・全方模擬'],corpus:['集典籍，存其版本。','從公開目錄建立來源索引，按需檢索已取得的核心全文。','典籍目錄・全文'],frameworks:['辨其理，留其脈絡。','整理九種中醫分析框架，保留各典籍的適用邊界。','分析框架'],quant:['以原詞編碼，以未知留白。','比較本草條目的序位與文獻詞涵蓋，檢查不同假設。','特性量化'],benchmark:['先見經方，再察藥對。','模擬已有方的文獻輪廓，核對獨立方義與同現頻數。','經方與藥對'],formulas:['集原方，析其元素。','從原方成分、炮製與方義原文，建立可追溯的配伍語料。','方劑語料'],inference:['由配伍結構，推估文獻藥性。','以已錄方義作對照，呈現組合推估、元素關聯與分組驗證。','藥性反推'],discovery:['由文獻線索，提出新假設。','在明示約束中探索組合，保留排序假設與來源。','配伍假設']});const t=titles[view];$('#page-title').textContent=t[0];$('#page-subtitle').textContent=t[1];$('#crumb').textContent=t[2];document.querySelectorAll('.nav-button').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});const content=$('#view-content');if(view!=='workbench')WorkbenchUI.dispose();if(view==='workbench'){WorkbenchUI.render(workbenchContext());renderResults();renderCitation()}else if(view==='library'){content.innerHTML=`<div class="library-controls"><input class="search" id="herb-search" placeholder="搜尋藥名、性味或典籍" aria-label="搜尋本草" value="${escape(query)}"><div class="filters" id="catalog-filters">${filtersHTML()}</div><select class="library-review-select" id="library-review" aria-label="本草核對狀態"><option value="">全部狀態</option><option value="reviewed" ${reviewFilter==='reviewed'?'selected':''}>節錄已核 24 條</option><option value="automatic" ${reviewFilter==='automatic'?'selected':''}>自動擷取 316 條</option></select></div><div class="notice">性味與歸經以本頁所列典籍為準；生品、炮製品與同名藥材須分別核對。未錄資料不能當作無毒或無禁忌。</div><p class="image-coverage"><span>${HerbImages.coverage()}</span><span>藥材照片・原植物・古籍藥圖分別標註</span><a href="downloads/herb-image-catalog.json" download>下載圖片來源清單 ↗</a></p><div class="library-grid" id="library-grid"></div>`;renderLibraryCards()}else if(view==='classics'){renderClassics()}else{const researchContext={selection:()=>selected,name:()=>formulaName,origin:()=>loadedCorpusFormula||data.formulas.find(f=>f.id===loadedFormulaId)||null,processing:options=>currentProcessing(options),massContext:()=>({...massContext}),notify,loadFormula:id=>{loadFormula(id);view='workbench';render()},stage:(rows,name)=>{HerbModel.validateSelection(rows,data);weightBasis='research';massContext={stage:'unrecorded',batch:'',source:''};preparation='unrecorded';processPlan=WorkstationModel.defaultPlan();selected=rows.map(x=>({...seedRow(x.id),...x,role:'未標註'}));formulaName=name;loadedFormulaId='';loadedCorpusFormula=null;analyzeCurrent();view='workbench';render();notify('已載入待審假設；各味是等權文獻比較')},showDetail,stageCorpus:(f)=>{const refs=f.ingredientRefs.filter(x=>x.id&&herb(x.id)&&x.scope!=='auxiliary');const ids=[...new Set(refs.map(x=>x.id))];massContext={stage:'unrecorded',batch:'',source:''};preparation='unrecorded';processPlan=WorkstationModel.defaultPlan();selected=ids.map(id=>seedRow(id,refs.find(r=>r.id===id)));formulaName=f.name+' · 新語料子集';loadedFormulaId='';loadedCorpusFormula=f;analyzeCurrent();view='workbench';render();notify('已載入可映射子集；原方未解析材料保留於來源說明')}};if(view==='forward'){HerbVectorUI.render(researchContext)}else if(['formulas','inference'].includes(view)){InferenceUI.render(view,researchContext)}else ResearchUI.render(view,researchContext)}}
function workbenchContext(){return {selection:()=>selected,name:()=>formulaName,basis:()=>weightBasis,massContext:()=>massContext,loadedFormulaId:()=>loadedFormulaId,origin:()=>loadedCorpusFormula||data.formulas.find(f=>f.id===loadedFormulaId)||null,processing:()=>currentProcessing(),preparation:()=>preparation,processPlan:()=>processPlan,setPreparation:v=>{preparation=v;WorkbenchUI.refresh()},updatePlan:patch=>{processPlan={...processPlan,...patch};WorkbenchUI.updateLive()},notify,updateRow:updateMaterial,query:()=>query,catalogCards,filtersHTML,validateInputs:validateVisibleRatios,renderResults,renderCitation,setBasis:v=>{if(!validateVisibleRatios()){const el=$('#weight-basis');if(el)el.value=weightBasis;return}weightBasis=v;WorkbenchUI.refresh();renderResults()},setMassContext:patch=>{massContext={...massContext,...patch};WorkbenchUI.updateLive()}}}
function renderSelection(){if(view!=='workbench')return;ProcessingUI.bindContext(workbenchContext());WorkbenchUI.refresh();renderCitation()}
function renderCitation(){if(loadedCorpusFormula){const panel=$('#formula-citation');if(panel)panel.innerHTML=InferenceUI.citation(loadedCorpusFormula);return}const f=data.formulas.find(f=>f.id===loadedFormulaId);const missing=(f?.ingredientRefs||[]).filter(x=>!x.id||x.mappingStatus==='unresolved');const panel=$('#formula-citation');if(!panel)return;panel.innerHTML=f?`<span class="citation-icon" aria-hidden="true">“</span><div><h3>${escape(f.name)} · 原方線索</h3><blockquote>${escape(f.ingredientSummary)}</blockquote><p>${escape(f.note)}</p>${missing.length?`<div class="notice">未解析成分：${missing.map(x=>escape(x.sourceName)).join('、')}。工作台只載入已解析子集，不能代表完整原方。</div>`:''}<p>${sourceLink(f.sourceId)} · 載入時各味份數均為 1，不還原原方劑量。</p></div>`:`<span class="citation-icon" aria-hidden="true">“</span><div><h3>自選組方 · 文獻研究</h3><blockquote>點選本草名稱，即可查閱該味藥的原文與出處。</blockquote><p>自選組方不代表典籍已有此方；結構標註是研究者的解讀。</p></div>`}
function renderResults(){if(view!=='workbench')return;WorkbenchUI.updateLive();if(!$('#analysis-state')||!$('#chart-body')||!$('#insight-body'))return;const stale=isStale();$('#analysis-state').innerHTML=stale?'<span class="stale">組方已變更，請重新模擬</span>':analyzed?'已模擬':'待模擬';const chart=$('#chart-body');const insights=$('#insight-body');if(!analyzed||!analyzed.selection.length){chart.innerHTML='<p class="empty-state">加入本草後，點選「模擬配伍」。</p>';insights.innerHTML='<p>模擬將核對已收錄的傳統相反藥對與毒性記載。</p><p class="rule-note">本平台未完成個人用藥或所有交互作用評估。</p>';return}const snapshot=analyzedProcessing,fmt=ProcessingUI.fmt,nature=analyzed.nature,fields=[['flavors','五味標籤'],['meridians','歸經標籤']];const caption=analyzed.canAggregate?`${fmt(analyzed.totalWeight)} ${escape(analyzed.weightUnit)}`:'全方克數未完整';const distribution=analyzed.canAggregate?`<div class="mini-title">性味標籤分布</div><div class="nature-bars" role="img" aria-label="${escape(nature.map(x=>`${x.label} ${fmt(x.percent)}%`).join('，'))}">${nature.map(x=>`<div style="width:${x.percent}%;background:${colors[x.label]}"></div>`).join('')}</div><div class="nature-legend">${nature.map(x=>`<span><i class="legend-dot" style="background:${colors[x.label]}"></i>${escape(x.label)} ${fmt(x.percent)}%</span>`).join('')}</div>${fields.map(([field,label])=>`<div class="chart-section"><div class="mini-title">${label}</div>${analyzed[field].map(x=>`<div class="meridian-row"><span>${escape(x.label)}</span><div class="bar-track"><div class="bar-fill" style="width:${x.percent}%;${x.label==='未錄'?'background:#b0b4ab':''}"></div></div><small>${fmt(x.percent)}%</small></div>`).join('')}</div>`).join('')}`:`<div class="mass-incomplete"><strong>全方質量分布：未知</strong><p>已錄子集 ${fmt(snapshot.knownGrams)} g；${snapshot.missingGrams.map(id=>escape(herb(id).name)).join('、')} 尚未填寫克數。補齊後重新模擬，才計算全方占比。</p></div>`;chart.innerHTML=`<p class="chart-caption">${analyzed.selection.length} 味本草 · ${caption}${stale?' · 上次模擬':''}</p>${distribution}${snapshot.changes.length?`<div class="processing-chart-changes"><div class="mini-title">所選炮製分支</div>${snapshot.changes.map(x=>`<div class="process-comparison"><strong>${escape(x.name)} · ${escape(x.processingLabel)}</strong><p>${escape(x.before.nature||'性未錄')} → ${escape(x.after.nature||'性未錄')}<br><span class="table-note">${escape(x.comparisonStatus)}</span></p></div>`).join('')}</div>`:''}<p class="rule-note">依所選炮製分支的文獻標籤與${analyzed.weightBasis==='grams'?'完整實錄克數':'研究份數'}計算；多個味或歸經平均分攤權重。「未錄」保留未知。占比與寒熱序位不表示實際藥效；工藝實錄沒有任意增減倍率。</p>`;if(stale){insights.innerHTML='<div class="status-label has-warnings"><span class="status-symbol">!</span>組方已變更，核對結果待更新</div><p>請點選「模擬配伍」核對目前組方。上次警示與成分重疊已隱藏。</p><p class="rule-note">待更新不代表安全；本平台未完成個人用藥或所有交互作用評估。</p>';return}const compat=analyzed.warnings.filter(w=>w.type==='compatibility');const toxic=analyzed.warnings.filter(w=>w.type==='toxicity');insights.innerHTML=`<div class="status-label ${analyzed.warnings.length?'has-warnings':''}"><span class="status-symbol">${analyzed.warnings.length?'!':'i'}</span>${analyzed.warnings.length?`命中 ${compat.length} 組配伍記載 · ${toxic.length} 味核對提示`:'已收錄配伍規則未命中'}</div>${!analyzed.warnings.length?'<p>目前未命中本資料庫的相反藥對與毒性提示。</p>':''}${analyzed.warnings.map(w=>{if(w.type==='compatibility')return `<div class="alert-item"><strong>${escape(herb(w.a).name)} × ${escape(herb(w.b).name)}</strong><p>${w.references.map(r=>`<span class="evidence-label">${r.evidenceType==='historical'?'歷史文獻':'官方使用注意'}</span><p>${escape(r.note)}</p>${r.quote&&r.evidenceType==='historical'?`<p class="alert-quote">「${escape(r.quote)}」</p>`:''}${sourceLink(r.sourceId,'查看配伍記載')}`).join('')}</div>`;return `<div class="alert-item toxic-alert"><strong>${escape(herb(w.herbId).name)} · 毒性與身份核對</strong><p>${escape(w.note)}</p>${sourceLink(w.sourceId,'查看毒性資料')}</div>`}).join('')}<p class="rule-note">未出現警示，不代表安全。本資料庫只收錄 3 組來源規則，未涵蓋 340 條的全部配伍。本平台未完成個人用藥、炮製、品質或所有交互作用評估；歷史「反」與「無毒」均非現代安全結論。</p><div class="match-row"><strong>與已收錄經方的成分重疊</strong>${analyzed.matches.slice(0,3).map(m=>`<div class="match-item"><span>${escape(data.formulas.find(f=>f.id===m.id).name)}</span><b>${Math.round(m.percent)}%${m.unresolvedIngredientNames?.length?' · 原方未完整解析':''}</b></div>`).join('')}<div class="match-meta">共同成分 ÷ 全部不同成分，忽略份數；不表示方義、療效或替代關係。</div></div>`}
function renderLibraryCards(){const grid=$('#library-grid');if(!grid)return;const found=filteredHerbs();libraryPage=Math.min(libraryPage,Math.max(0,Math.ceil(found.length/24)-1));grid.innerHTML=found.length?found.slice(libraryPage*24,(libraryPage+1)*24).map(h=>`<article class="library-card">${HerbImages.thumb(h.id,'card')}<div class="library-card-head"><h2>${escape(h.name)}</h2><span class="herb-image-kind">${HerbImages.label(h.id)}</span></div><div>${[h.nature,...h.flavors||[],...h.meridians||[]].filter(Boolean).map(x=>`<span class="tag">${escape(x)}</span>`).join('')}</div><p>${escape(h.summary)}</p>${ResearchUI.badge(h)}${h.toxic?'<p class="risk-copy">含毒性或身份核對提示</p>':''}<div class="library-card-actions"><button class="button secondary" data-detail="${escape(h.id)}">藥圖與原文</button><button class="button secondary" data-add="${escape(h.id)}">${selected.some(s=>s.id===h.id)?'已加入':'加入組方'}</button></div><p class="source-caption">${escape(source(h.sourceId)?.title||'來源未錄')}</p></article>`).join(''):'<p class="empty-state">沒有符合的本草。</p>';grid.insertAdjacentHTML('beforeend',`<div class="library-pagination pager"><span>${found.length} 條結果・第 ${libraryPage+1} / ${Math.max(1,Math.ceil(found.length/24))} 頁</span><button class="button secondary" id="library-prev" ${libraryPage===0?'disabled':''}>上一頁</button><button class="button secondary" id="library-next" ${(libraryPage+1)*24>=found.length?'disabled':''}>下一頁</button></div>`)}
function renderClassics(){ $('#view-content').innerHTML=`<div class="classics-grid">${[...new Map(data.sources.filter(s=>s.kind!=='modern').map(s=>[s.title,s])).values()].map(s=>`<article class="panel classic-card"><span class="eyebrow">CLASSICAL SOURCE</span><h2>${escape(s.title)}</h2><p>${escape(s.note||'本平台採用線上轉錄本，研究時應再核對底本。')}<br>收錄 ${data.sources.filter(x=>x.title===s.title).length} 個條目來源</p>${sourceLink(s.id,'閱讀典籍原文')}</article>`).join('')}</div><section class="panel method"><h2>模擬方法與資料邊界</h2><h3>01 · 研究份數與屬性分布</h3><p>每味本草可設 1 至 20 個研究份數。性味依「溫熱、平性、寒涼、需辨加工、未錄」分組；每味的多個味或歸經，平均分攤該味份數。比例 = 該標籤所分攤份數 ÷ 全組方份數。這是資料描述，不能預測藥性強度。</p><h3>炮製、工藝與實錄質量</h3><p>炮製分支只採用該分支明載且有原文位置的屬性，其餘保留未知。克數由研究者實錄，稱量階段與批次另存；古代兩、錢、枚等保留原文。只有全部材料的克數完整時，才以質量占比描述文獻標籤。溫度、時間與媒介實錄不自動轉成藥效係數。</p><p><a class="small-link" href="downloads/processing-profiles.json" download>炮製來源資料 ↗</a> · <a class="small-link" href="downloads/processing-methodology.json" download>炮製與計量方法 ↗</a></p><h3>02 · 配伍規則</h3><p>逐對核對下列文獻記載；只要兩味均存在，便顯示提示，不隨研究份數減少而消失。有毒或身份提示獨立計算。歷史記載不等同已被現代研究確認的機制。</p>${data.rules.map(r=>`<div class="rule-card"><strong>${escape(r.name||'相反藥對')}</strong><p>${escape(r.quote)}</p><p>${escape(r.note)}</p>${sourceLink(r.sourceId)}</div>`).join('')}<h3>03 · 經方的成分重疊</h3><p>採 Jaccard 集合比例：所選組方與經方的共同成分數，除以兩者全部不同成分數。忽略研究份數、炮製、煎煮與結構標註，不能據此判定同方、同效或替代關係。</p><h3>04 · 版本與身份對應</h3>${data.formulas.map(f=>`<p><strong>${escape(f.name)}：</strong>${escape(f.note)} ${sourceLink(f.sourceId)}</p>`).join('')}<p>本草屬性依各味所列《本草備要》或《神農本草經》版本；泛稱條目跨加工性味時列為「需辨加工」，原方成分來自各方所列典籍。文獻間的名稱、炮製或屬性差異需要另行考證；古籍中「無毒」是歷史分類。</p><h3>05 · 現代毒性資料</h3>${data.sources.filter(s=>s.kind==='modern').map(s=>`<p>${escape(s.note)} ${sourceLink(s.id)}</p>`).join('')}<div class="notice">未收錄不等於不存在；未命中不等於安全。此工具不處理症狀診斷、個人體質、孕哺狀態、其他藥物、真實服用劑量、煎煮或品質檢驗。</div><p class="table-note">資料核對日：2026 年 10 月 4 日 · 線上古籍轉錄本可能與其他版本不同。</p></section>`}
function showDetail(id){const h=herb(id);if(!h)return;$('#detail-content').innerHTML=`<div class="eyebrow">MATERIA MEDICA · ${escape(h.id.toUpperCase())}</div><h2>${escape(h.name)}</h2>${ResearchUI.badge(h)}<div>${[h.nature,...h.flavors||[],...h.meridians||[]].filter(Boolean).map(x=>`<span class="tag">${escape(x)}</span>`).join('')}</div>${h.aliases?.length?`<p class="table-note">別名／對應：${escape(h.aliases.join('、'))}</p>`:''}<p>${escape(h.summary)}</p>${h.identityNote?`<div class="notice">${escape(h.identityNote)}</div>`:''}${HerbImages.gallery(h.id)}<h3 class="detail-heading">典籍摘錄</h3><blockquote>${escape(h.quote||'原文尚未收錄')}</blockquote><p>${sourceLink(h.sourceId)}${h.section?` · ${escape(h.section)}`:''}</p>${h.toxic?`<div class="alert-item"><strong>毒性與身份核對</strong><p>${escape(h.toxic.note||h.toxic)}</p>${sourceLink(h.toxic.sourceId,'查看補充資料')}</div>`:''}<details><summary>查看特徵原詞與定位</summary><div class="detail-evidence">${(h.evidenceSpans||[]).map(e=>`<p><strong>${escape({nature:'性',flavors:'味',meridians:'歸經',effects:'功用'}[e.field]||e.field)}</strong>「${escape(e.text)}」<br><small>原文 Unicode 字符 ${e.start}–${e.end}；${escape(e.basis)}</small></p>`).join('')||'尚無結構化原文位置'}</div></details><p class="rule-note">原文缺項保留未知；現代基原、藥理與安全尚未完成核定。本頁呈現古籍內容摘要。性味、歸經與「無毒」等記載是文獻分類，並非現代用藥安全結論。</p><button class="button primary" data-add="${escape(h.id)}">${selected.some(s=>s.id===h.id)?'已在組方中':'加入組方'}</button>`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal()}
function validateVisibleRatios(){if(!ProcessingUI.validateInputs()||!WorkbenchUI.validatePlanInputs())return false;for(const input of document.querySelectorAll('[data-ratio]')){const value=Number(input.value);if(!Number.isInteger(value)||value<1||value>20){input.reportValidity();notify('請填寫 1 至 20 的研究份數');return false}}return true}
function exportResearch(){if(!validateVisibleRatios())return;if(!selected.length){notify('請先加入本草再匯出');return}const processing=currentProcessing();const result=processing.analysis;const record={title:formulaName||'未命名配伍研究',createdAt:new Date().toISOString(),dataReviewedAt:'2026-10-04',purpose:'典籍配伍研究；非診斷、療效預測或服用建議',weightUnit:weightBasis==='grams'?'研究者實錄質量g；不是自動服用量':'相對研究份數；非克數或服用劑量',selection:selected.map(s=>({...s,name:herb(s.id).name,sourceId:herb(s.id).sourceId,identityNote:herb(s.id).identityNote||null,imageReferences:HerbImages.record(s.id)})),analysis:result,quantitativeTextProfile:processing.quant,processingAndMass:processingRecord(processing),workflowSnapshot:WorkbenchFlow.snapshot(selected,processing,{basis:weightBasis,massContext,name:formulaName}),operationSnapshot:WorkstationModel.snapshot(selected,processing,{basis:weightBasis,massContext,name:formulaName,origin:loadedCorpusFormula||data.formulas.find(f=>f.id===loadedFormulaId)||null,preparation,processPlan}),operationSources:window.WORKSTATION_SOURCES,formulaComposition:loadedFormulaId?data.formulas.find(f=>f.id===loadedFormulaId):loadedCorpusFormula,compositionSubsetNotice:loadedCorpusFormula?'僅可映射目錄子集；原方未映射元素保留於formulaComposition，不代表完整原方':null,method:{distribution:'按所選研究份數或完整實錄克數分配文獻標籤，未知保留未錄；非劑量藥效模型',formulaOverlap:'Jaccard 成分集合重疊，忽略份數與炮製差異',roles:'研究者自行標註',safety:'未命中警示不代表安全'},sources:loadedCorpusFormula?[...data.sources,...window.FORMULA_CORPUS.sources]:data.sources};const blob=new Blob([JSON.stringify(record,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='本草配伍研究-'+new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('研究記錄已匯出，含當前組方與來源')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){if(view==='workbench'&&!validateVisibleRatios())return;view=b.dataset.view;render();window.scrollTo({top:0});return}if(b.id==='library-prev'||b.id==='library-next'){libraryPage+=b.id==='library-next'?1:-1;renderLibraryCards();return}if(b.dataset.filter){libraryPage=0;filter=b.dataset.filter;renderCatalog();return}if(b.dataset.detail){showDetail(b.dataset.detail);return}if(b.dataset.add){if(view==='workbench'&&!validateVisibleRatios())return;addHerb(b.dataset.add);return}if(b.dataset.remove){if(!validateVisibleRatios())return;selected=selected.filter(s=>s.id!==b.dataset.remove);loadedFormulaId='';loadedCorpusFormula=null;changed();return}if(b.dataset.step){if(!validateVisibleRatios())return;const s=selected.find(s=>s.id===b.dataset.id);if(s){s.ratio=Math.max(1,Math.min(20,s.ratio+Number(b.dataset.step)));changed()}return}if(b.id==='analyze'){if(!validateVisibleRatios())return;analyzeCurrent();renderResults();notify(analyzed.canAggregate?'已完成炮製文獻與配伍核對':'克數未完整；保留質量未知，成分核對已完成');return}if(b.id==='reset'){WorkbenchUI.reset();$('#view-content').innerHTML='';selected=[];analyzed=null;analyzedProcessing=null;loadedFormulaId='';loadedCorpusFormula=null;formulaName='我的配伍研究';weightBasis='grams';massContext={stage:'unrecorded',batch:'',source:''};preparation='unrecorded';processPlan=WorkstationModel.defaultPlan();render();notify('已清空組方');return}if(b.id==='export'){exportResearch();return}if(b.classList.contains('dialog-close'))$('#detail-dialog').close()});
document.addEventListener('input',e=>{if(e.target.dataset.ratio){const s=selected.find(s=>s.id===e.target.dataset.ratio);if(!s)return;if(e.target.value===''){e.target.setCustomValidity('研究份數須為 1 至 20 的整數');return}const value=Number(e.target.value);if(!Number.isInteger(value)||value<1||value>20){e.target.value=s.ratio;e.target.setCustomValidity('');notify('研究份數須為 1 至 20 的整數');return}s.ratio=value;e.target.setCustomValidity('');const group=e.target.parentElement;group.querySelector('[data-step="-1"]').disabled=value<=1;group.querySelector('[data-step="1"]').disabled=value>=20;renderResults()}if(e.target.id==='herb-search'){query=e.target.value;libraryPage=0;renderCatalog()}if(e.target.id==='formula-name'){formulaName=e.target.value;WorkbenchUI.updateLive()}});
document.addEventListener('change',e=>{if(e.target.id==='library-review'){reviewFilter=e.target.value;libraryPage=0;renderLibraryCards()}if(e.target.id==='template'&&e.target.value){if(!validateVisibleRatios()){e.target.value=loadedFormulaId||'';return}loadFormula(e.target.value);render()}if(e.target.dataset.ratio){const s=selected.find(s=>s.id===e.target.dataset.ratio);const value=Number(e.target.value);if(!Number.isInteger(value)||value<1||value>20){e.target.value=s.ratio;e.target.setCustomValidity('');notify('研究份數須為 1 至 20 的整數');return}e.target.setCustomValidity('');s.ratio=value;changed()}if(e.target.dataset.role){const s=selected.find(s=>s.id===e.target.dataset.role);if(s&&roleOptions.includes(e.target.value)){s.role=e.target.value;WorkbenchUI.updateLive()}}});
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('.brand').addEventListener('click',e=>{e.preventDefault();if(view==='workbench'&&!validateVisibleRatios())return;view='workbench';render()});
const firstFormula=data.formulas.find(f=>f.id==='sijunzi')||data.formulas[0];if(firstFormula)loadFormula(firstFormula.id,false);render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_formula_research',title:'讀取配伍研究',description:'讀取目前組方及按文獻規則計算的分析；不改變畫面，不判定用藥安全。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length)throw new Error('此操作不接受參數');return {title:formulaName,selection:selected.map(s=>({...s,name:herb(s.id).name})),analysis:currentProcessing().analysis,textProfile:currentProcessing().quant,processingAndMass:processingRecord(),operationSnapshot:WorkstationModel.snapshot(selected,currentProcessing(),{basis:weightBasis,massContext,name:formulaName,origin:loadedCorpusFormula||data.formulas.find(f=>f.id===loadedFormulaId)||null,preparation,processPlan}),limitations:"文獻編碼；未完成獨立留出、現代身份及藥理驗證"}}},{name:'configure_formula_research',title:'設定配伍研究',description:'以已收錄本草 ID 和 1 至 20 的研究份數取代目前組方，並更新工作台與文獻分析；份數不是服用劑量。',inputSchema:{type:'object',properties:{herbs:{type:'array',items:{type:'object',properties:{id:{type:'string'},ratio:{type:'integer',minimum:1,maximum:20}},required:['id','ratio'],additionalProperties:false}}},required:['herbs'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='herbs')||!Array.isArray(input.herbs)||input.herbs.some(h=>!h||Object.keys(h).some(k=>!['id','ratio'].includes(k))))throw new Error('組方格式無效');HerbModel.validateSelection(input.herbs,data);const next=input.herbs.map(s=>({...seedRow(s.id),...s}));weightBasis='research';massContext={stage:'unrecorded',batch:'',source:''};preparation='unrecorded';processPlan=WorkstationModel.defaultPlan();selected=next;const processing=analyzeCurrent(),result=processing.analysis;loadedFormulaId='';loadedCorpusFormula=null;formulaName='自選配伍研究';view='workbench';render();return {selection:selected.map(s=>({...s})),warnings:result.warnings,nature:result.nature}}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
